UPDATE products SET specs = specs || jsonb_build_object('informacaoAdicional', E'BENEFÍCIOS\nExcelente controle de manuseio em alta velocidade e menor ruído.\nControle de alta velocidade\nManuseio incomparável em termos de conforto e durabilidade na estrada, especialmente em caso de danos causados por buracos.\nMaior aderência e segurança excepcional em manobras muito bruscas.\nCARACTERÍSTICA\nGeometria variável da ranhura.\nProjeto de piso simétrico.\nGrande área de contato.\nParedes de alta resistência e mais legíveis.') WHERE id='a55b7ee2-142e-4cb0-aff6-91262861302e';